CREATE OR REPLACE FUNCTION public._flag_review_keyword_hit(_content text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _kw text;
  _norm text;
  _gap text;
BEGIN
  IF _content IS NULL OR length(btrim(_content)) = 0 THEN
    RETURN NULL;
  END IF;
  FOR _kw IN
    SELECT keyword FROM public.blocked_keywords
    WHERE is_active = true AND severity = 'flag_review'
      AND keyword IS NOT NULL AND length(btrim(keyword)) > 0
  LOOP
    _norm := lower(regexp_replace(_kw, '[^a-zA-Z0-9]', '', 'g'));
    CONTINUE WHEN _norm = '';
    _gap := '\y' || regexp_replace(_norm, '(.)', '\1[^a-zA-Z0-9]*', 'g') || '\y';
    IF _content ~* _gap THEN
      RETURN _kw;
    END IF;
  END LOOP;
  RETURN NULL;
END;
$function$

FN|enforce_comment_blocklist():
CREATE OR REPLACE FUNCTION public.enforce_comment_blocklist()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _kw text;
  _norm_kw text;
  _gap text;
BEGIN
  IF NEW.content IS NULL OR length(btrim(NEW.content)) = 0 THEN
    RETURN NEW;
  END IF;
  FOR _kw IN
    SELECT keyword FROM public.blocked_keywords
    WHERE is_active = true AND severity = 'auto_hide' AND keyword IS NOT NULL AND length(btrim(keyword)) > 0
  LOOP
    -- normalize the keyword to alphanumerics only (chars are then all regex-safe)
    _norm_kw := lower(regexp_replace(_kw, '[^a-zA-Z0-9]', '', 'g'));
    CONTINUE WHEN _norm_kw = '';
    -- build boundary-anchored gap pattern: k[^alnum]*w[^alnum]*...
    _gap := '\y' || regexp_replace(_norm_kw, '(.)', '\1[^a-zA-Z0-9]*', 'g') || '\y';
    IF NEW.content ~* _gap THEN
      RAISE EXCEPTION 'Comment blocked by content filter' USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$function$

FN|expire_gift_credit(_gift_id uuid):
CREATE OR REPLACE FUNCTION public.expire_gift_credit(_gift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _gift    record;
  _balance numeric;
  _deduct  numeric;
BEGIN
  -- Lock the gift row: a concurrent run blocks, then sees is_expired and skips.
  SELECT id, user_id, amount, reason, is_expired
  INTO _gift
  FROM public.gift_announcements
  WHERE id = _gift_id
  FOR UPDATE;

  IF _gift IS NULL THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'not_found');
  END IF;
  IF _gift.is_expired THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'already_expired');
  END IF;

  SELECT balance INTO _balance FROM public.wallets WHERE user_id = _gift.user_id;
  _deduct := LEAST(COALESCE(_gift.amount, 0), COALESCE(_balance, 0));

  IF _deduct > 0 THEN
    -- reference_id/type tag makes the debit idempotent via uq_wallet_txn_gift_expiry.
    PERFORM public.wallet_transaction(
      _gift.user_id,
      'gift_expiry',
      -_deduct,
      'Gift credit expired: "' || COALESCE(_gift.reason, '') || '"',
      _gift.id,
      'gift_expiry',
      jsonb_build_object('expired_gift_id', _gift.id, 'original_amount', _gift.amount)
    );
  END IF;

  UPDATE public.gift_announcements SET is_expired = true WHERE id = _gift_id;

  RETURN jsonb_build_object('expired', true, 'deducted', _deduct);
END;
$function$

