FN|get_lesson_content(_lesson_id uuid):
CREATE OR REPLACE FUNCTION public.get_lesson_content(_lesson_id uuid)
 RETURNS TABLE(id uuid, title text, content text, video_url text, image_url text, sort_order integer, course_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_lesson public.lessons%ROWTYPE;
  v_course public.courses%ROWTYPE;
  v_is_privileged boolean := false;
BEGIN
  SELECT * INTO v_lesson FROM public.lessons l WHERE l.id = _lesson_id;
  IF NOT FOUND THEN
    RETURN;                       -- unknown lesson -> zero rows ("not found")
  END IF;

  SELECT * INTO v_course FROM public.courses c WHERE c.id = v_lesson.course_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_uid IS NOT NULL THEN
    v_is_privileged :=
         v_course.author_id = v_uid
      OR public.has_role(v_uid, 'admin'::app_role);
      -- NOTE: live app_role enum has no 'super_admin' value; 'admin' is the
      -- only elevated role (matches the certificates admin RLS policy).
  END IF;

  -- Unpublished courses: only author/admin may read (same as courses RLS)
  IF v_course.status <> 'published' AND NOT v_is_privileged THEN
    RETURN;                       -- behave as "not found", don't leak existence
  END IF;

  IF v_course.is_free
     OR v_is_privileged
     OR (v_uid IS NOT NULL AND EXISTS (
           SELECT 1 FROM public.course_enrollments e
           WHERE e.user_id = v_uid AND e.course_id = v_course.id))
  THEN
    RETURN QUERY SELECT
      v_lesson.id, v_lesson.title, v_lesson.content, v_lesson.video_url,
      v_lesson.image_url, v_lesson.sort_order, v_lesson.course_id;
  ELSE
    RAISE EXCEPTION 'Enrollment required to view this lesson'
      USING ERRCODE = '42501';    -- insufficient_privilege
  END IF;
END;
$function$

