CREATE OR REPLACE FUNCTION public.get_profile_visible_fields(_target uuid)
 RETURNS TABLE(avatar_url text, bio text, photography_interests text[], portfolio_url text, facebook_url text, instagram_url text, twitter_url text, youtube_url text, website_url text, current_city text, workplace text, education text, pronouns text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _is_owner boolean := (_caller IS NOT NULL AND _caller = _target);
  _is_admin boolean := (_caller IS NOT NULL AND public.has_role(_caller, 'admin'::app_role));
  _is_friend boolean := (_caller IS NOT NULL AND public.are_friends(_caller, _target));
  ps jsonb;
  p public.profiles%ROWTYPE;
  -- visibility helper values
  _priv boolean := (_is_owner OR _is_admin);           -- sees only_me
  _frnd boolean := (_is_owner OR _is_admin OR _is_friend); -- sees friends
BEGIN
  SELECT * INTO p FROM public.profiles WHERE id = _target;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  ps := COALESCE(p.privacy_settings, '{}'::jsonb);

  RETURN QUERY SELECT
    CASE WHEN public._field_visible(ps->>'avatar',      _frnd, _priv) THEN p.avatar_url    ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'bio',         _frnd, _priv) THEN p.bio           ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'interests',   _frnd, _priv) THEN p.photography_interests ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'portfolio',   _frnd, _priv) THEN p.portfolio_url ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'social_links',_frnd, _priv) THEN p.facebook_url  ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'social_links',_frnd, _priv) THEN p.instagram_url ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'social_links',_frnd, _priv) THEN p.twitter_url   ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'social_links',_frnd, _priv) THEN p.youtube_url   ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'social_links',_frnd, _priv) THEN p.website_url   ELSE NULL END,
