    CASE WHEN public._field_visible(ps->>'education',    _frnd, _priv) THEN p.education     ELSE NULL END,
    CASE WHEN public._field_visible(ps->>'pronouns',    _frnd, _priv) THEN p.pronouns      ELSE NULL END;
END;
