FN|issue_course_completion_certificate(_:
CREATE OR REPLACE FUNCTION public.issue_course_completion_certificate(_course_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _course record;
  _total_lessons int;
  _completed_lessons int;
  _existing_id uuid;
  _new_id uuid;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT id, title INTO _course
  FROM public.courses
  WHERE id = _course_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Course not found';
  END IF;

  -- Gate 1: must be enrolled (enrollment is created only by enroll_in_course,
  -- which already enforces payment + published status).
  IF NOT EXISTS (
    SELECT 1 FROM public.course_enrollments
    WHERE user_id = _uid AND course_id = _course_id
  ) THEN
    RAISE EXCEPTION 'Not enrolled in this course';
  END IF;

  -- Gate 2: every lesson of the course completed.
  SELECT count(*) INTO _total_lessons
  FROM public.lessons
  WHERE course_id = _course_id;

  IF _total_lessons = 0 THEN
    RAISE EXCEPTION 'Course has no lessons';
  END IF;

  SELECT count(DISTINCT lp.lesson_id) INTO _completed_lessons
  FROM public.lesson_progress lp
  JOIN public.lessons l ON l.id = lp.lesson_id
  WHERE lp.user_id = _uid
    AND l.course_id = _course_id
    AND lp.completed = true;

  IF _completed_lessons < _total_lessons THEN
    RAISE EXCEPTION 'Course not complete: % of % lessons finished',
      _completed_lessons, _total_lessons;
  END IF;

  -- Idempotency: one completion certificate per (user, course), ever.
  -- Deliberately does NOT exclude revoked rows — re-issuing after an admin
  -- revocation must stay an admin decision, not a self-service loophole.
  SELECT id INTO _existing_id
  FROM public.certificates
  WHERE user_id = _uid
    AND type = 'course_completion'
    AND reference_id = _course_id
  ORDER BY issued_at ASC
  LIMIT 1;

  IF _existing_id IS NOT NULL THEN
    RETURN _existing_id;
  END IF;

  -- Title/description strings byte-match the current client writer
  -- (CourseDetail.tsx:85-86) so Certificates.tsx's
  -- `.replace(" — Completion Certificate", "")` keeps working.
  INSERT INTO public.certificates (user_id, type, title, description, reference_id)
  VALUES (
    _uid,
    'course_completion',
    _course.title || ' — Completion Certificate',
    'Successfully completed all ' || _total_lessons || ' lessons in "' || _course.title || '".',
    _course_id
  )
  RETURNING id INTO _new_id;

  RETURN _new_id;
END;
$function$

FN|password_verification_hook(event json:
CREATE OR REPLACE FUNCTION public.password_verification_hook(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := (event->>'user_id')::uuid;
  _valid boolean := COALESCE((event->>'valid')::boolean, false);
  _row public.auth_login_attempts;
  _lock_seconds integer := 0;
  _remaining integer;
BEGIN
  SELECT * INTO _row FROM public.auth_login_attempts WHERE user_id = _uid FOR UPDATE;

  -- Currently locked -> reject even a correct password until the lock expires.
  IF _row.locked_until IS NOT NULL AND _row.locked_until > now() THEN
    _remaining := CEIL(EXTRACT(EPOCH FROM (_row.locked_until - now())))::integer;
    RETURN jsonb_build_object(
      'decision', 'reject',
      'message', 'Too many failed sign-in attempts. Try again in ' || _remaining || ' seconds.',
      'should_logout_user', false
    );
  END IF;

  IF _valid THEN
    DELETE FROM public.auth_login_attempts WHERE user_id = _uid;
    RETURN jsonb_build_object('decision', 'continue');
  END IF;

  -- Failed attempt: reset stale counters (1h quiet window), then increment.
  IF _row.user_id IS NULL OR _row.last_attempt < now() - interval '1 hour' THEN
    INSERT INTO public.auth_login_attempts AS a (user_id, failed_count, last_attempt, locked_until)
    VALUES (_uid, 1, now(), NULL)
    ON CONFLICT (user_id) DO UPDATE SET failed_count = 1, last_attempt = now(), locked_until = NULL
    RETURNING * INTO _row;
  ELSE
    UPDATE public.auth_login_attempts
    SET failed_count = failed_count + 1, last_attempt = now()
    WHERE user_id = _uid
    RETURNING * INTO _row;
  END IF;

  _lock_seconds := CASE
    WHEN _row.failed_count >= 10 THEN 900
    WHEN _row.failed_count >= 7  THEN 300
    WHEN _row.failed_count >= 5  THEN 120
    WHEN _row.failed_count >= 3  THEN 30
    ELSE 0
  END;

  IF _lock_seconds > 0 THEN
    UPDATE public.auth_login_attempts
    SET locked_until = now() + make_interval(secs => _lock_seconds)
    WHERE user_id = _uid;
    RETURN jsonb_build_object(
      'decision', 'reject',
      'message', 'Too many failed sign-in attempts. Try again in ' || _lock_seconds || ' seconds.',
      'should_logout_user', false
    );
  END IF;

  -- Let GoTrue return its normal invalid-credentials error.
  RETURN jsonb_build_object('decision', 'continue');
END;
$function$

